  static readonly layerTest: (on: ReadonlyArray<string> | ((p: string) => ReadonlyArray<string>)) => Layer.Layer<Flags>;
}
// 0..99, the same every time for one participant and flag (FNV-1a of `${flag}:${participant}`)
export function bucket(participant: string, flag: string): number;

export const requireAdmin: MiddlewareHandler<Vars>;
// no live sign-in → 401 { rejected: 'sign in first' }
// not an admin    → 403 { rejected: `admins only; ${accountId} is not an admin` }

FlagRow   = { name, enabled: boolean, allowlist: ParticipantId[], percent: 0..100 }
FlagPatch = Partial<Omit<FlagRow, 'name'>>   // a missing key keeps the stored value
GET /flags       → 200 { flags: FlagRow[] }
PUT /flags/:name → 200 { flag: FlagRow } | 400 { rejected: 'invalid flag <name>: …' }

GET /admin/summary  → { accounts, admins, signIns, flags, flagsOn, events, streams }
GET /admin/accounts → { accounts: { accountId, email, name, admin, openedAt, liveSignIns }[] }
GET /admin/events?stream=&limit=50 → { events: { stream, version, type, by, at, data }[] }
// in data, every key matching /hash|password|token/i is '•••'; limit is 1..200

